$ErrorActionPreference = "Stop"
$path = "C:\Users\xteri\Desktop\421п_Замалиев_2026_КП_Учёт_заявок.docx"
$word = New-Object -ComObject Word.Application
$word.Visible = $false
$word.DisplayAlerts = 0
$doc = $null
try {
    $doc = $word.Documents.Open($path)
    $sel = $word.Selection

    function P([string]$text, [string]$style) {
        $sel.Style = $doc.Styles.Item($style)
        $sel.Font.Bold = 0
        $sel.Font.Italic = 0
        $sel.Font.Name = "Times New Roman"
        $sel.TypeText($text)
        $sel.TypeParagraph()
    }

    function Add-Grid($rows) {
        $sel.Style = $doc.Styles.Item("CourseBody")
        $sel.Font.Bold = 0
        $sel.ParagraphFormat.FirstLineIndent = 0
        $n = $rows.Count
        $m = $rows[0].Count
        $table = $doc.Tables.Add($sel.Range, $n, $m)
        $table.Borders.Enable = $true
        $table.Range.Font.Name = "Times New Roman"
        $table.Range.Font.Size = 12
        $table.Range.Font.Bold = 0
        $table.Range.ParagraphFormat.FirstLineIndent = 0
        $table.Range.ParagraphFormat.Alignment = 0
        for ($r = 0; $r -lt $n; $r++) {
            for ($c = 0; $c -lt $m; $c++) {
                $cell = $table.Cell($r + 1, $c + 1).Range
                $cell.Text = [string]$rows[$r][$c]
                $cell.Font.Name = "Times New Roman"
                $cell.Font.Size = 12
                $cell.Font.Bold = 0
                $cell.ParagraphFormat.FirstLineIndent = 0
            }
        }
        $table.Rows.Item(1).Range.Font.Bold = 1
        $table.Rows.Item(1).Range.ParagraphFormat.Alignment = 1
        $end = $table.Range.End
        $sel.SetRange($end, $end)
        $sel.TypeParagraph()
        $sel.Font.Bold = 0
    }

    function Find-Heading([string]$starts, [string]$style) {
        foreach ($p in $doc.Paragraphs) {
            $t = ($p.Range.Text -replace "[\r\a]", "").Trim()
            $s = [string]$p.Range.Style.NameLocal
            if ($t.StartsWith($starts) -and $s -eq $style) { return $p }
        }
        throw "Не найден абзац: $starts"
    }

    function Begin-Insert($para) {
        $sel.SetRange($para.Range.Start, $para.Range.Start)
        $sel.TypeParagraph() | Out-Null
        $sel.MoveUp(4, 1) | Out-Null
    }

    $guide = Find-Heading "ЗАКЛЮЧЕНИЕ" "CourseFront"
    Begin-Insert $guide

    P "5.1 Запуск окна и сайта" "CourseHeading2"
    P "Окно сотрудников и сайт запускаются из одного решения. В Visual Studio открывают настройку начальных проектов и ставят запуск для ServiceCenter.Avalonia и ServiceCenter.Blazor. Проект ServiceCenter.Data сам по себе не запускается: это общая библиотека моделей и правил. Сервер PostgreSQL должен быть запущен раньше окна, иначе список заявок останется пустым." "CourseBody"
    P "Сайт в профиле https открывается по адресу https://localhost:7095. Браузер может предупредить о локальном сертификате, для учебной проверки переход подтверждают. Профиль http использует адрес http://localhost:5093. Окно появляется отдельно, в заголовке написано «Учёт заявок сервисного центра». Значок приложения виден на панели задач и у ярлыка, внутри рабочей области его нет." "CourseBody"
    P "Оба контура пишут в базу ServiceCenter. Заявка с сайта после обновления списка видна диспетчеру. Заявка, введённая в окне, на главной странице сайта списком не публикуется: клиент открывает её по номеру и своему телефону. Повторный запуск не создаёт вторую копию тестовых сотрудников и не стирает уже добавленные строки." "CourseBody"

    P "5.2 Вход и выход" "CourseHeading2"
    P "Форма входа содержит поля «Логин» и «Пароль» и кнопку «Войти». Символы пароля на экране закрыты. Пустые поля, неверная пара и отключённая учётная запись дают одну и ту же надпись «Неверный логин или пароль». Форма при этом не закрывается, данные в базе не меняются." "CourseBody"
    P "Для проверки подготовлены три записи. Администратор входит логином admin и паролем admin123. Диспетчер входит логином dispatcher и паролем dispatcher123. Мастер входит логином master и паролем master123. В базе хранится не сам пароль, а его хеш. После успешного входа слева открывается панель, справа сразу показывается список заявок." "CourseBody"
    P "В верхней части списка видны фамилия сотрудника и его роль. Кнопка «Выход» стоит внизу панели. Она завершает сеанс и возвращает форму входа. Заявки, клиенты и справочники при выходе сохраняются. Следующий сотрудник входит заново и видит только то меню, которое положено его роли." "CourseBody"
    P "Администратор видит пункты «Заявки», «Клиенты», «Справочники», «Сотрудники» и «Статистика», а также кнопку новой заявки. У диспетчера нет справочников и сотрудников. У мастера нет клиентов, справочников, сотрудников и кнопки новой заявки. Скрытый пункт нельзя открыть обходным адресом: в окне нет отдельных адресов страниц, состав меню задаётся ролью после входа." "CourseBody"

    P "5.3 Список заявок" "CourseHeading2"
    P "Над списком расположены поле «Клиент или неисправность», раскрывающийся список статусов и кнопки «Найти», «Сбросить» и «Новая заявка». Поиск сравнивает введённый фрагмент с фамилией клиента и с текстом неисправности без учёта регистра. Если выбран статус, остаются только заявки этого статуса. Кнопка «Сбросить» очищает оба условия и показывает полный список роли." "CourseBody"
    P "Строка показывает номер, клиента, неисправность, статус и мастера. Длинное имя переносится внутри своей колонки и не сливается с текстом неисправности. Если мастер ещё не назначен, в последней колонке стоит «не назначен». Над строками выводится число найденных заявок, чтобы было видно, сработал фильтр или список и правда короткий." "CourseBody"
    P "Одиночный щелчок строку не редактирует. Карточка открывается двойным щелчком. Мастер видит только те заявки, где он указан исполнителем. Чужая строка у него не появится, даже если текст неисправности совпал с поиском. Поэтому пустой список у мастера чаще всего значит, что диспетчер ещё не назначил ему работу, а не то, что заявок нет в базе." "CourseBody"
    P "Кнопка «Новая заявка» есть у администратора и диспетчера. Мастер новую карточку не создаёт: он ведёт уже назначенную работу, меняет допустимый статус и пишет комментарий. Если нужно принять устройство, это делает диспетчер или администратор." "CourseBody"

    P "5.4 Новая заявка в окне" "CourseHeading2"
    P "Форма «Новая заявка» требует клиента, тип устройства, услугу и текст неисправности. Срок необязателен и вводится как дата в виде ГГГГ-ММ-ДД, например 2026-11-20. Пустой срок сохраняется как отсутствие даты. Кнопка «Назад» возвращает к списку и ничего не записывает." "CourseBody"
    P "Если обязательное поле пустое, запись не создаётся и на форме остаётся пояснение. Клиента, которого ещё нет в списке, сначала добавляют на экране «Клиенты», затем выбирают в форме. Устройство и услуга берутся только из справочника. Произвольное название в эти поля вписать нельзя, иначе в базе появились бы заявки без связи со справочником." "CourseBody"
    P "После сохранения статус всегда «Принята», а источник помечает, что заявку ввёл сотрудник. В журнал статусов пишется первая строка с этим сотрудником. Карточка открывается сразу, чтобы можно было назначить мастера, не возвращаясь к поиску только что созданной строки." "CourseBody"

    P "5.5 Карточка заявки" "CourseHeading2"
    P "Карточка показывает номер, клиента, устройство, услугу, текущий статус, источник, мастера и срок. Источник «сайт» означает, что обращение пришло с формы клиента. Источник сотрудника означает, что заявку ввели в окне. Под этими сведениями расположен текст неисправности так, как его сохранили, без отдельного редактора уже записанного текста." "CourseBody"
    P "Блок назначения виден администратору и диспетчеру. В списке только активные сотрудники с ролью мастера. Кнопка «Назначить» записывает выбранного человека в заявку. Если список пуст, сначала создают сотрудника с ролью мастера и включённым признаком «Активен». Назначение не меняет статус само по себе: перевод в работу выполняется отдельно." "CourseBody"
    P "Новый статус выбирается из справочника и подтверждается кнопкой «Сменить статус». Переход проверяется по роли и по текущему коду. Разрешённые пары собраны в табл. 5.1. Запрещённый переход не записывается: на карточке остаётся прежний статус и текст «Такой переход статуса для вашей роли запрещён». Тот же отказ будет, если выбрать уже установленный статус." "CourseBody"
    P "Таблица 5.1 - Разрешённые переходы статуса" "CourseTableCaption"
    Add-Grid @(
        @("Откуда", "Куда", "Кто может"),
        @("Принята", "В работе", "Администратор, диспетчер, мастер"),
        @("Принята", "Отменена", "Администратор, диспетчер, мастер"),
        @("В работе", "Готова", "Администратор, диспетчер, мастер"),
        @("В работе", "Отменена", "Администратор, диспетчер, мастер"),
        @("Готова", "Закрыта", "Администратор или диспетчер"),
        @("Закрыта", "В работе", "Только администратор")
    )
    P "Мастер не может закрыть заявку, даже если она уже в статусе «Готова». Закрытие оставляет диспетчер, когда клиент забирает устройство, или администратор. Вернуть закрытую заявку в работу может только администратор, например если неисправность проявилась снова. Остальные роли такой переход не проходят." "CourseBody"
    P "Комментарий вводится в нижнее поле и добавляется кнопкой «Добавить комментарий». В списке видны дата, сотрудник и текст. Пустое поле не записывается. Мастер добавляет комментарий только к своей заявке. Эти строки на сайте не показываются: клиент видит номер, устройство, услугу и название статуса." "CourseBody"
    P "Кнопка «Назад» возвращает к списку. Если перед этим статус или мастер были сохранены, список при открытии читает базу заново и показывает уже новое значение. Несохранённый выбор в раскрывающемся списке без нажатия кнопки в базу не попадает." "CourseBody"

    P "5.6 Клиенты" "CourseHeading2"
    P "Экран «Клиенты» доступен администратору и диспетчеру. Слева расположен список, справа поля «ФИО», «Телефон» и «Примечание». Щелчок по строке заполняет поля, и кнопка «Сохранить» обновляет выбранного человека. Кнопка «Новый» очищает форму. Следующее сохранение тогда добавляет запись, а не затирает предыдущую." "CourseBody"
    P "Телефон лучше вводить так, как его потом назовёт клиент на сайте. Проверка статуса сравнивает только цифры, поэтому запись +7 900 000-00-00 совпадёт с вводом 89000000000, если набор цифр один и тот же. Пустые фамилия или телефон не записываются. Примечание можно оставить пустым." "CourseBody"
    P "Клиент, созданный формой сайта, тоже попадает в этот список. В примечании такой записи указано, что она создана с сайта. Диспетчер может поправить имя, если человек ошибся при наборе, и эта правка не меняет уже выданный номер заявки. Удаление клиента с экрана не предусмотрено, чтобы не оставить заявку без владельца." "CourseBody"
    P "место для рисунка" "CourseCaption"
    P "Рисунок 5.5 - Экран клиентов" "CourseCaption"

    P "5.7 Справочники" "CourseHeading2"
    P "Экран «Справочники» есть только у администратора. На нём два рабочих списка: типы устройств и услуги. Новое название вводится в поле и добавляется кнопкой «Добавить». Выбранную строку удаляют кнопкой «Удалить выбранный». Пустое название не добавляется." "CourseBody"
    P "Удаление не проходит, если тип или услуга уже указаны в заявке. На экране остаётся сообщение, что значение используется. Так нельзя получить заявку без устройства или без услуги. Статусы на этом экране только перечислены. Удалить их нельзя: от их кодов зависят переходы из табл. 5.1." "CourseBody"
    P "Новая услуга сразу доступна и в форме окна, и на сайте. Отдельной публикации нет. Если на сайте всё ещё виден старый набор, страницу обновляют: справочник читается при открытии, а не хранится отдельной копией для клиента. Начальный набор содержит смартфон, ноутбук и планшет, а также диагностику, замену экрана и чистку." "CourseBody"

    P "5.8 Сотрудники" "CourseHeading2"
    P "Экран «Сотрудники» тоже открывается только администратору. В строке списка видны имя, логин, роль и пометка «отключён», если вход запрещён. Выбор строки заполняет форму. Кнопка «Сохранить» меняет логин, имя, роль и признак активности. Пароль при правке можно оставить пустым: тогда прежний хеш не меняется. Новый пароль записывается, только если поле заполнено." "CourseBody"
    P "Кнопка «Новый» очищает форму и снимает выбор. Для новой записи пароль обязателен, иначе появляется текст «Укажите пароль». Повтор уже занятого логина не сохраняется, сообщение говорит «Такой логин уже занят». Роль выбирается одна: администратор, диспетчер или мастер. Совмещать роли в одной учётной записи нельзя." "CourseBody"
    P "Снятый флажок «Активен» запрещает вход, но не стирает заявки этого человека. Отключение заменяет удаление: мастер больше не входит и не попадает в список назначения, а история его заявок остаётся. Включать учётную запись обратно можно тем же флажком и кнопкой «Сохранить»." "CourseBody"
    P "место для рисунка" "CourseCaption"
    P "Рисунок 5.6 - Экран сотрудников" "CourseCaption"

    P "5.9 Статистика" "CourseHeading2"
    P "Экран «Статистика» помечен как только чтение и кнопок записи не содержит. Сверху выводится число заявок и число закрытых. Ниже строки сгруппированы по статусу и по мастеру. Администратор и диспетчер видят все заявки. Мастер видит сводку только по тем заявкам, где исполнителем указан он." "CourseBody"
    P "Экран нужен, чтобы оценить очередь, а не чтобы заменить карточку. Если число в сводке не сходится со списком, сначала проверяют фильтр списка: поиск или выбранный статус могли скрыть часть строк. Статистика фильтр списка не учитывает и всегда считает заявки роли целиком." "CourseBody"

    P "5.10 Сайт для клиента" "CourseHeading2"
    P "Сайт открывается без логина сотрудника. В шапке стоят название «Сервисный центр» и пункты «Главная», «Услуги», «Заявка», «Статус», «Контакты». На главной кратко описан приём, перечислены услуги и типы устройств из базы и три шага: оставить заявку, дождаться работы мастера и проверить номер. Стоимость на главной не указана." "CourseBody"
    P "Страница «Услуги» повторяет справочник и предлагает перейти к форме. Срок и цену называет диспетчер после осмотра, поэтому на сайте их нет. Страница «Контакты» содержит учебный адрес в Казани, телефон +7 900 000-00-00 и часы ежедневно с 10:00 до 20:00. Там же напоминание, что готовое устройство выдаёт диспетчер по номеру заявки и телефону." "CourseBody"
    P "Форма «Заявка» просит ФИО, телефон, тип устройства, услугу и неисправность. Все пять полей обязательны, в телефоне должно быть не меньше десяти цифр. После отправки на экране остаётся номер. Его нужно записать: без номера страница статуса заявку не найдёт. Кнопка на этом экране ведёт к проверке статуса." "CourseBody"
    P "Если цифры телефона уже есть у клиента в базе, новая заявка привязывается к нему, а не создаёт второго человека с тем же номером. Новый телефон создаёт клиента с пометкой, что запись пришла с сайта. Статус такой заявки - «Принята», источник - сайт. Комментарий мастера к ней на сайте не появится." "CourseBody"
    P "Страница «Статус» спрашивает номер и телефон и ищет их при каждом нажатии «Показать». Поэтому смена статуса в окне видна клиенту после повторной проверки, а не по старой открытой надписи. Чужой телефон или несуществующий номер дают сообщение, что заявка не найдена. В ответе указаны номер, устройство, услуга и название статуса." "CourseBody"
    P "Главная страница номер конкретной заявки не выводит. Если после работы в окне сайт «не изменился», открывают именно «Статус», вводят номер и телефон и нажимают «Показать». Обновление главной меняет только состав услуг и типов устройств, если администратор правил справочник." "CourseBody"
    P "место для рисунка" "CourseCaption"
    P "Рисунок 5.7 - Проверка статуса на сайте" "CourseCaption"

    P "5.11 Если действие не проходит" "CourseHeading2"
    P "Пустой список у администратора при первом запуске означает, что база не заполнилась. Проверяют, что служба PostgreSQL запущена, затем закрывают окно и открывают его снова. Тестовая заявка «Не включается после падения» и клиент Иванов Иван должны появиться вместе с тремя учётными записями. Уже введённые вручную строки повторный запуск не удаляет." "CourseBody"
    P "Если мастер не видит заявку, её нужно открыть под диспетчером и назначить этого мастера. Если кнопка смены статуса отвечает запретом, смотрят табл. 5.1 и текущую роль: закрытие недоступно мастеру, возврат из «Закрыта» недоступен диспетчеру. Обходить запрет правкой таблицы для обычной работы не требуется." "CourseBody"
    P "Если сайт открыт, а новая услуга или новый статус не видны, страницу обновляют и для статуса снова нажимают «Показать». Окно и сайт должны быть запущены вместе с доступной базой. Выход из окна сеанс сотрудника заканчивает, но сайт для клиента при этом продолжает работать." "CourseBody"

    $conc = Find-Heading "СПИСОК ИСПОЛЬЗОВАННЫХ ИСТОЧНИКОВ" "CourseFront"
    Begin-Insert $conc
    P "Проверка ролей показала, что отдельная программа на каждую должность не нужна. Администратор ведёт сотрудников и справочники. Диспетчер принимает обращение, назначает мастера и закрывает готовую работу. Мастер видит только свои заявки и не ставит статус «Закрыта». Клиент не получает форму входа сотрудников и не читает внутренние комментарии." "CourseBody"
    P "Общая база убирает разрыв между окном и сайтом. Номер, который форма показывает клиенту, совпадает с номером в списке диспетчера. Поле источника отличает обращение с сайта от записи, введённой сотрудником. Журнал статусов хранит, кто выполнил переход, поэтому спорный шаг можно сверить не по памяти, а по строке журнала." "CourseBody"
    P "В первую версию сознательно не входят оплата, склад запчастей, SMS и учётная запись клиента с паролем. Для курсового проекта достаточно провести заявку от приёма до закрытия и увидеть ту же строку в pgAdmin. Эти ограничения не мешают ролям и статусам: стоимость или уведомление можно добавить позже, не меняя уже принятый порядок работы." "CourseBody"
    P "Таким образом, поставленные задачи выполнены. Описаны сценарии, таблицы и средства разработки, собраны окно и сайт, заданы правила статуса, подготовлены порядок проверки и руководство пользователя. Система пригодна для демонстрации на локальном сервере PostgreSQL: сотрудник ведёт заявку по своей роли, клиент оставляет обращение и узнаёт статус по номеру и телефону." "CourseBody"

    if ($doc.TablesOfContents.Count -ge 1) {
        $doc.TablesOfContents.Item(1).Update()
    }
    $doc.Save()

    $doc.Repaginate()
    $pages = $doc.ComputeStatistics(2)
    Write-Output "PAGES $pages"
    foreach ($p in $doc.Paragraphs) {
        $s = [string]$p.Range.Style.NameLocal
        $t = ($p.Range.Text -replace "[\r\a]", "").Trim()
        if ($s -match "CourseFront|CourseHeading1" -and $t.Length -gt 0) {
            $page = $p.Range.Information(3)
            Write-Output ("{0,3} | {1}" -f $page, $t.Substring(0, [Math]::Min(70, $t.Length)))
        }
    }
}
finally {
    if ($doc -ne $null) { $doc.Close() }
    $word.Quit()
}
